//! tamias-driver-peregrin — the tamias content **driver** for
//! `peregrin-bundle`. tamias discovers this on `PATH` /
//! `<tamias-home>/drivers/` and runs
//! `<driver> <verb> --dir <d> --name <n> [--config <c>]`.
//!
//! Verbs: `install` (no-op — the node config is generated by `deploy`,
//! which sees the stable store dir; `install` only sees the
//! evictable fetch-cache payload), `deploy` (regenerate the operator
//! node config from the manifest's `provider:` block), `uninstall`
//! (remove it). Service units are rendered by `tamias deploy` from
//! `provider.services[]` — the driver never writes them. Thin wrapper
//! over `peregrin_cli::provision`.

use std::path::PathBuf;
use std::process::ExitCode;

use clap::{Parser, Subcommand};
use peregrin_cli::provision;

#[derive(Parser)]
#[command(name = "tamias-driver-peregrin", version)]
struct Cli {
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Subcommand)]
enum Cmd {
    /// No-op — node config materialization is `deploy`'s job (it sees
    /// the stable store dir; install only sees the fetch cache).
    Install {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Regenerate the operator node config (provider.services units
    /// are rendered by `tamias deploy`, not this verb).
    Deploy {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Remove the node config + any legacy unit.
    Uninstall {
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Report the content types + verbs this driver handles (JSON).
    Capabilities,
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    let result = match cli.cmd {
        Cmd::Install { .. } => {
            println!("install: node config is generated by `tamias deploy` — nothing to do");
            return ExitCode::SUCCESS;
        }
        Cmd::Deploy { dir, name, config } => provision::deploy(&dir, &name, config.as_deref()),
        Cmd::Uninstall { name, config } => provision::uninstall(&name, config.as_deref()),
        Cmd::Capabilities => {
            println!(
                "{{\"types\":[\"peregrin-bundle\"],\"verbs\":[\"install\",\"deploy\",\"uninstall\"]}}"
            );
            return ExitCode::SUCCESS;
        }
    };
    match result {
        Ok(line) => {
            println!("{line}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("tamias-driver-peregrin: {e}");
            ExitCode::FAILURE
        }
    }
}
